let patientState={status:"Critical",icon:"🔴",condition:"Cardiac arrest detected"};const PATIENT_STATES={critical:{status:"Critical",icon:"🔴",condition:"Cardiac arrest detected"},unstable:{status:"Unstable",icon:"🟠",condition:"Emergency room prepared. Waiting for intervention."},arrhythmia:{status:"Arrhythmia",icon:"❤️",condition:"Abnormal heart rhythm detected."},improving:{status:"Improving",icon:"🟡",condition:"Defibrillator ready. Patient responding."},stabilized:{status:"Stabilized",icon:"🟢",condition:"Vital signs restored."}};function updatePatientState(t){PATIENT_STATES[t]&&(patientState=PATIENT_STATES[t],updatePatientHUD())}function updatePatientHUD(){const t=document.getElementById("hud-patient");t&&(t.innerHTML=`\n\n        ${patientState.icon}\n\n        ${patientState.status}\n\n        <br>\n\n        <small>\n            ${patientState.condition}\n        </small>\n\n    `)}